import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B7aBQbI5.js";var i=JSON.parse(`{"title":"The offline history journal","description":"","frontmatter":{},"headers":[],"relativePath":"history.md","filePath":"pages/history.md"}`),a={name:`history.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="the-offline-history-journal" tabindex="-1">The offline history journal <a class="header-anchor" href="#the-offline-history-journal" aria-label="Permalink to “The offline history journal”">​</a></h1><ul><li><a href="#grapht-history">grapht-history</a></li><li><a href="#the-jsonl-format">The JSONL format</a></li><li><a href="#historyrevision">HistoryRevision</a></li><li><a href="#hash-verification">Hash verification</a></li><li><a href="#structural-anomalies">Structural anomalies</a></li></ul><h2 id="grapht-history" tabindex="-1">grapht-history <a class="header-anchor" href="#grapht-history" aria-label="Permalink to “grapht-history”">​</a></h2><p><code>grapht-history</code> walks git for one diagram file and writes a self-contained journal. Run it from the repository that holds the file:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>grapht-history &lt;diagram-path&gt; [journal-path]</span></span></code></pre></div><p>With no journal path it writes to <code>&lt;diagram-path&gt;.history.jsonl</code>. It prints the revision count and exits nonzero if it found structural anomalies. The entry point is <code>historyMain</code> (<code>packages/grapht/src/5_history/2_cli.ts:7</code>); the walk is <code>gitHistoryJournal</code> (<code>packages/grapht/src/5_history/1_gitWalk.ts:18</code>).</p><p>The walk uses <code>git log --follow --reverse</code> over the path and <code>git show &lt;rev&gt;:&lt;path&gt;</code> for each commit, so the journal carries every revision of the file in oldest-first order.</p><h2 id="the-jsonl-format" tabindex="-1">The JSONL format <a class="header-anchor" href="#the-jsonl-format" aria-label="Permalink to “The JSONL format”">​</a></h2><p>The journal is JSON Lines: one header line, then one line per revision (<code>packages/grapht/src/5_history/0_journal.ts:31</code>).</p><table tabindex="0"><thead><tr><th>line</th><th>content</th></tr></thead><tbody><tr><td>header</td><td><code>{ &quot;format&quot;: &quot;grapht-history/0&quot;, &quot;artifactId&quot;, &quot;path&quot; }</code></td></tr><tr><td>each revision</td><td>one <code>HistoryRevision</code> object</td></tr></tbody></table><p>The <code>format</code> field names the record and gates every reader; <code>jsonlToJournal</code> rejects anything else (<code>src/5_history/0_journal.ts:44</code>).</p><h2 id="historyrevision" tabindex="-1">HistoryRevision <a class="header-anchor" href="#historyrevision" aria-label="Permalink to “HistoryRevision”">​</a></h2><p>Each revision is self-contained: it carries its own content, so a consumer reconstructs any revision without git or the repository present. Declared at <code>packages/grapht/src/5_history/0_journal.ts:5</code>.</p><table tabindex="0"><thead><tr><th>field</th><th>meaning</th></tr></thead><tbody><tr><td><code>artifactId</code></td><td>which artifact the journal is about</td></tr><tr><td><code>revisionId</code></td><td>the git commit hash</td></tr><tr><td><code>parentRevisionIds</code></td><td>the commit&#39;s parents</td></tr><tr><td><code>contentHash</code></td><td>sha256 of <code>content</code></td></tr><tr><td><code>capturedAt</code></td><td>ISO 8601 commit timestamp, from ingest</td></tr><tr><td><code>message</code></td><td>the commit subject</td></tr><tr><td><code>path</code></td><td>the file path</td></tr><tr><td><code>content</code></td><td>the file at that revision</td></tr></tbody></table><h2 id="hash-verification" tabindex="-1">Hash verification <a class="header-anchor" href="#hash-verification" aria-label="Permalink to “Hash verification”">​</a></h2><p>Every read verifies the content. <code>contentHashOf(content)</code> is sha256 hex (<code>src/5_history/0_journal.ts:26</code>). <code>jsonlToJournal</code> recomputes it for each revision and throws on a mismatch (<code>src/5_history/0_journal.ts:47</code>), so a journal that was edited, truncated, or corrupted on disk fails loudly instead of replaying a wrong revision.</p><h2 id="structural-anomalies" tabindex="-1">Structural anomalies <a class="header-anchor" href="#structural-anomalies" aria-label="Permalink to “Structural anomalies”">​</a></h2><p><code>journalAnomalies(journal)</code> names structural defects without touching content (<code>packages/grapht/src/5_history/0_journal.ts:55</code>): a duplicate revision id, or a revision captured before its predecessor in the list. The CLI prints these to stderr and exits nonzero, while still writing the journal, so a broken history is visible and not silently accepted.</p>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};